// Note that we don't yet support `indirect` for enums.
// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.
/**
 * This account's relationship to a room.
 *
 * The roster is filtered with `new_filter_non_left`, so an **invited** room
 * is listed exactly like a joined one — and until this field existed the
 * webview could not tell the two apart. That is issue #1: 32 agent rooms
 * arrived as invites, each rendering as a room with one unreadable state
 * event in it and no way to accept, because nothing in the wire format said
 * "this is an invitation".
 *
 * Carried as an enum rather than an `is_invite` boolean: `Knocked` and
 * `Banned` are states the SDK can report, and a boolean would have to fold
 * them into "joined", which is the kind of lie that costs a second bug
 * later.
 */

public enum Membership {
    
    case joined
    case invited
    case left
    case knocked
    case banned
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeMembership: FfiConverterRustBuffer {
    typealias SwiftType = Membership

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Membership {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .joined
        
        case 2: return .invited
        
        case 3: return .left
        
        case 4: return .knocked
        
        case 5: return .banned
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: Membership, into buf: inout [UInt8]) {
        switch value {
        
        
        case .joined:
            writeInt(&buf, Int32(1))
        
        
        case .invited:
            writeInt(&buf, Int32(2))
        
        
        case .left:
            writeInt(&buf, Int32(3))
        
        
        case .knocked:
            writeInt(&buf, Int32(4))
        
        
        case .banned:
            writeInt(&buf, Int32(5))
        
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeMembership_lift(_ buf: RustBuffer) throws -> Membership {
    return try FfiConverterTypeMembership.lift(buf)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeMembership_lower(_ value: Membership) -> RustBuffer {
    return FfiConverterTypeMembership.lower(value)
}



